import joblib

class SimpleModelRegistry:
    def __init__(self):
        self.versions = {}
        self.production_version = None

    def register(self, model, version, stage="staging"):
        self.versions[version] = {"model": model, "stage": stage}
        print(f"Registered version {version} in stage '{stage}'")

    def promote_to_production(self, version):
        if self.production_version is not None:
            self.versions[self.production_version]["stage"] = "archived"
            print(f"Version {self.production_version} moved to archived")
        self.versions[version]["stage"] = "production"
        self.production_version = version
        print(f"Version {version} promoted to production")

    def get_production_model(self):
        return self.versions[self.production_version]["model"]

    def rollback_to(self, version):
        print(f"Rolling back from version {self.production_version} to version {version}")
        self.promote_to_production(version)

registry = SimpleModelRegistry()
registry.register(model="model_v1_object", version="v1", stage="staging")
registry.promote_to_production("v1")

registry.register(model="model_v2_object", version="v2", stage="staging")
registry.promote_to_production("v2")  # v1 automatically moves to archived

print(f"\nCurrently serving: {registry.get_production_model()}")

registry.rollback_to("v1")
print(f"After rollback, currently serving: {registry.get_production_model()}")
